#define LUNGO_UINT32 5
#define LUNGO_UINT64 6
#define LUNGO_USIZE 7
#define LUNGO_INT8 8
#define LUNGO_INT16 9
#define LUNGO_INT32 10
#define LUNGO_INT64 11
#define LUNGO_ISIZE 12
#define LUNGO_FLOAT 13
#define LUNGO_FLOAT32 14
#define LUNGO_CHAR 15
#define LUNGO_STRING 16
#define LUNGO_UNIT 17
#define LUNGO_BYTE_ARRAY 18
#define LUNGO_FLOAT_ARRAY 19
#define LUNGO_OPTION 20
