/* Kinds of errors. */
#define LUNGO_ERROR_IO 0
#define LUNGO_ERROR_VALUE 1
#define LUNGO_ERROR_MALFORMED 2

/* A host function: runs with its context and `n` borrowed arguments; returns LUNGO_OK and
   stores its result (owned) in `*result`, or returns LUNGO_FAILED and stores an error (owned)
   in `*error`. */
typedef int32_t (*lungo_function)(void *ctx, const lungo_value *const *args, size_t n, lungo_value **result,
                                  lungo_error **error);
typedef void (*lungo_drop)(void *ctx);

