int32_t lungo_invoke(const lungo_types *types, lungo_entry entry, const uint8_t *sig, size_t sig_len,
                     const lungo_type *const *type_args, size_t n_types, const lungo_value *const *args, size_t n_args,
                     lungo_value **result, lungo_error **error);
